import {chromium} from '@playwright/test';import fs from 'node:fs/promises';import assert from 'node:assert/strict';import {KEY,scenarioState} from '../src/model.js';
const dir='检查记录/复盘回看_20261022',browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true,args:['--no-proxy-server']}),p=await browser.newPage(),results=[],errors=[];p.setDefaultTimeout(7000);p.on('pageerror',e=>errors.push(e.message));
async function load(lang,width,scene='PT05'){await p.setViewportSize({width,height:width===390?844:1000});await p.goto('http://127.0.0.1:5184/plan');await p.evaluate(({s,key,lang})=>{localStorage.setItem(key,JSON.stringify(s));localStorage.setItem('career-prototype-language',lang);localStorage.setItem('career-prototype-operation-guide-v1',JSON.stringify({enabled:false,neverPrompt:true}));},{s:scenarioState(scene),key:KEY,lang});await p.goto('http://127.0.0.1:5184/plan?tab=复盘');await p.locator('.action-review').waitFor();}
try{
for(const [lang,width,label] of [['zh',1440,'原因分析'],['en',1440,'Cause analysis'],['zh',390,'原因分析'],['en',390,'Cause analysis']]){
 try{await load(lang,width);await p.locator('textarea[name=result]').fill('Own observation (synthetic)');await p.locator('.review-journal button[type=submit]').click();const field=p.getByRole('textbox',{name:label,exact:true});assert.equal(await field.count(),1);assert.equal(await field.getAttribute('aria-label'),label);assert.equal(await field.locator('..').locator('span').first().innerText(),label);await p.waitForFunction(()=>document.activeElement?.getAttribute('name')==='reason');assert.equal(await field.evaluate(e=>document.activeElement===e),true);await field.fill('Own interpretation, still uncertain (synthetic)');await p.locator('.review-step-tabs button').first().click();await p.locator('.review-step-tabs button').nth(1).click();await p.waitForFunction(()=>document.activeElement?.getAttribute('name')==='reason');assert.equal(await field.inputValue(),'Own interpretation, still uncertain (synthetic)');assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);await p.screenshot({path:dir+'/实际截图/R1-'+width+'-'+lang+'-原因栏-视口.png'});results.push({name:lang+' '+width+'原因可见标签/accessible name一致，缺项聚焦且输入原样保留',status:'pass'});}catch(e){results.push({name:lang+' '+width+'原因栏',status:'fail',error:e.message});}
}
for(const [width,file] of [[1440,'desktop'],[390,'mobile']]){await load('zh',width,'PT01');await p.locator('.action-review').evaluate(e=>e.scrollIntoView({block:'start'}));await p.screenshot({path:'.impeccable/review/'+file+'.png'});await p.screenshot({path:dir+'/实际截图/R1-'+width+'-空态-视口.png'});}
assert.deepEqual(errors,[]);
}finally{await fs.writeFile(dir+'/R1可访问名称定向复核.json',JSON.stringify({results,errors,note:'仅复核独立reviewer的R1及直接回归，不是全站重测。'},null,2));await browser.close();}console.log(JSON.stringify({results,errors},null,2));if(errors.length||results.some(r=>r.status==='fail'))process.exitCode=1;
